static int helm_ring_norm(int a)
{
    a %= 360;
    return (a < 0) ? (a + 360) : a;
}

/** @brief trig(±32767) × r，四舍五入（不用 libm，板端与模拟器同一算法）。 */
static int helm_ring_trig(int32_t v, int r)
{
    int64_t p = (int64_t)v * r;

    if (p >= 0) {
        return (int)((p + 16384) / 32767);
    }
    return (int)((p - 16384) / 32767);
}

/** @brief 角度（0 = 12 点，顺时针）→ 页面根坐标。 */
static void helm_ring_pt(int angle, int r, int * x, int * y)
{
    int a = helm_ring_norm(angle);

    *x = HELM_RING_CX + helm_ring_trig(lv_trigo_sin((int16_t)a), r);
    *y = HELM_RING_CY - helm_ring_trig(lv_trigo_cos((int16_t)a), r);
}

/** @brief 模式身份色：骑行=ok、导航=BAN_NAV（蓝）、记录=NAV（橙）、设置=mute。
 *  @note 板端 `HELM_COLOR_NAV` 是橙色强调色；导航身份必须用横幅那支蓝
 *        （`HELM_COLOR_BAN_NAV`），否则罗盘上导航与记录同色、分不出来。 */
static uint32_t helm_ring_ink_hex(int mode)
{
    switch (mode & 3) {
    case 0:
        return HELM_COLOR_OK;
    case 1:
        return HELM_COLOR_BAN_NAV;
    case 2:
        return HELM_COLOR_NAV;
    default:
        return HELM_COLOR_MUTE;
    }
}

/** @brief 扇区 12px 浅色填充。设置没有专属 fill ⇒ 同色 20% 透明度。 */
static uint32_t helm_ring_fill_hex(int mode)
{
    switch (mode & 3) {
    case 0:
        return HELM_COLOR_OK_FILL;
    case 1:
        return HELM_COLOR_BAN_NAV_FILL;
    case 2:
        return HELM_COLOR_NAV_FILL;
    default:
        return HELM_COLOR_MUTE;
    }
}

static helm_icon_t helm_ring_icon_id(int mode)
{
    switch (mode & 3) {
    case 0:
        return HELM_ICON_BIKE;
    case 1:
        return HELM_ICON_NAV;
    case 2:
        return HELM_ICON_RECORD;
    default:
        return HELM_ICON_SETTINGS;
    }
}

/** @brief 30px 模式名（板端没有 30px 点阵档；正常固件走系统 TTF，工厂回退 22px）。 */
static const lv_font_t * helm_ring_name_font(void)
{
    return helm_font_sys(30, s_sh.font_val);
}

static void helm_ring_set_font(lv_obj_t * obj, const lv_font_t * font)
{
    if (obj != NULL && font != NULL &&
        lv_obj_get_style_text_font(obj, 0) != font) {
        lv_obj_set_style_text_font(obj, font, 0);
    }
}

/**
 * @brief 一段扇区弧（只画 indicator；主弧全透明）。
 * @param mode  0..3：角度 = mode*90−90±26（上/右/下/左）。
 * @param width 16 = 浅色填充，2 = 深色外沿。
 */
static lv_obj_t * helm_ring_arc_make(lv_obj_t * parent, int mode, int width,
                                     uint32_t hex, lv_opa_t opa)
{
    lv_obj_t * arc = lv_arc_create(parent);
    int a = (mode & 3) * 90 - 90;

    lv_obj_set_size(arc, HELM_RING_D, HELM_RING_D);
    lv_obj_set_pos(arc, HELM_RING_CX - HELM_RING_D / 2,
                   HELM_RING_CY - HELM_RING_D / 2);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_all(arc, 0, 0);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(arc, 0, 0);
    lv_obj_set_style_outline_width(arc, 0, 0);
    lv_obj_set_style_shadow_width(arc, 0, 0);
    /* 主弧不画，只留 indicator 扇段。 */
    lv_obj_set_style_arc_opa(arc, LV_OPA_TRANSP, LV_PART_MAIN);
    lv_obj_set_style_arc_width(arc, 0, LV_PART_MAIN);
    lv_obj_set_style_arc_rounded(arc, false, LV_PART_MAIN);
    lv_obj_set_style_arc_opa(arc, opa, LV_PART_INDICATOR);
    lv_obj_set_style_arc_width(arc, width, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(arc, helm_color(hex), LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(arc, false, LV_PART_INDICATOR);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, LV_PART_KNOB);
    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
    lv_obj_set_style_pad_all(arc, 0, LV_PART_KNOB);
    lv_arc_set_rotation(arc, 0);
    lv_arc_set_range(arc, 0, 100);
    lv_arc_set_value(arc, 100);
    lv_arc_set_bg_angles(arc, (lv_value_precise_t)helm_ring_norm(a - 26),
                         (lv_value_precise_t)helm_ring_norm(a + 26));
    /* R1-S7b：canvas 路径下扇区画在 ring art 里，这层弧只留给 CPU 回退。 */
    helm_ring_hide_legacy(arc);
    return arc;
}

