}

/** @brief 24 刻度：整点 3px（INK）、其余 1px（MUTE）。 */
static void helm_ring_build_ticks(lv_obj_t * parent)
{
    int i;

    for (i = 0; i < 24; i++) {
        const int deg = i * 15;
        const bool major = (i % 6) == 0;
        const int th = major ? 3 : 1;
        int x1, y1, x2, y2;
        int x, y, w, h;
        lv_obj_t * box;

        helm_ring_pt(deg, major ? HELM_RING_TICK_RIN_M : HELM_RING_TICK_RIN_m,
                     &x1, &y1);
        helm_ring_pt(deg, HELM_RING_TICK_ROUT, &x2, &y2);
        if (LV_ABS(x2 - x1) >= LV_ABS(y2 - y1)) {
            x = (x1 < x2) ? x1 : x2;
            y = y1;
            w = LV_ABS(x2 - x1) + 1;
            h = th;
        } else {
            x = x1;
            y = (y1 < y2) ? y1 : y2;
            w = th;
            h = LV_ABS(y2 - y1) + 1;
        }

        box = lv_obj_create(parent);
        lv_obj_remove_style_all(box);
        lv_obj_set_pos(box, x, y);
        lv_obj_set_size(box, w, h);
        lv_obj_set_style_bg_color(box,
            helm_color(major ? HELM_COLOR_INK : HELM_COLOR_MUTE), 0);
        lv_obj_set_style_bg_opa(box, LV_OPA_COVER, 0);
        lv_obj_set_style_radius(box, th / 2, 0);
        lv_obj_remove_flag(box, LV_OBJ_FLAG_CLICKABLE);
        lv_obj_clear_flag(box, LV_OBJ_FLAG_SCROLLABLE);
        /* R1-S7c：刻度保持可见（art 里已不含它）——静态层在 canvas 之上。 */
        s_sh.ring_tick[i] = box;
    }
}

/** @brief 指针：中心 → r=72 的杆 + 末端 8px 横杆。 */
static void helm_ring_pointer_layout(int32_t angle)
{
    const int a = helm_ring_norm((int)angle);
    const int32_t sn = lv_trigo_sin((int16_t)a);
    const int32_t cs = lv_trigo_cos((int16_t)a);
    const int sx = (int)sn;
    const int sy = (int)(-cs);
    const int px = (int)cs;
    const int py = (int)sn;
    const int x0 = HELM_RING_CX + helm_ring_trig(sx, HELM_RING_PTR_R0);
    const int y0 = HELM_RING_CY + helm_ring_trig(sy, HELM_RING_PTR_R0);
    const int x1 = HELM_RING_CX + helm_ring_trig(sx, HELM_RING_PTR_R1);
    const int y1 = HELM_RING_CY + helm_ring_trig(sy, HELM_RING_PTR_R1);

    s_sh.ring_ptr_pts[0].x = x0;
    s_sh.ring_ptr_pts[0].y = y0;
    s_sh.ring_ptr_pts[1].x = x1;
    s_sh.ring_ptr_pts[1].y = y1;
    s_sh.ring_cross_pts[0].x =
        x1 - helm_ring_trig(px, HELM_RING_PTR_CROSS);
    s_sh.ring_cross_pts[0].y =
        y1 - helm_ring_trig(py, HELM_RING_PTR_CROSS);
    s_sh.ring_cross_pts[1].x =
        x1 + helm_ring_trig(px, HELM_RING_PTR_CROSS);
    s_sh.ring_cross_pts[1].y =
        y1 + helm_ring_trig(py, HELM_RING_PTR_CROSS);
    if (s_sh.ring_ptr != NULL) {
        lv_line_set_points(s_sh.ring_ptr, s_sh.ring_ptr_pts, 2);
    }
    if (s_sh.ring_cross != NULL) {
        lv_line_set_points(s_sh.ring_cross, s_sh.ring_cross_pts, 2);
    }
}

/* ═══════════════════════════════════════════════════════════════════════════
 * R1-S7b：ring art（静态图）+ face（显示缓冲）+ EPIC 整层旋转
 * ═══════════════════════════════════════════════════════════════════════════ */

/** @brief 分配 art/face（各 80 KB + 32B 对齐余量）。失败返回 false。 */
static bool helm_ring_art_alloc(void)
{
    if (s_ring_art != NULL && s_ring_face != NULL) {
        return true;
    }

    if (s_ring_art_raw == NULL) {
        s_ring_art_raw = board_malloc_psram(HELM_RING_ART_BYTES +
                                            HELM_RING_ART_ALIGN);
    }
    if (s_ring_face_raw == NULL) {
        s_ring_face_raw = board_malloc_psram(HELM_RING_ART_BYTES +
                                             HELM_RING_ART_ALIGN);
    }
    if (s_ring_art_raw == NULL || s_ring_face_raw == NULL) {
        if (s_ring_art_raw != NULL) {
            board_free_psram(s_ring_art_raw);
            s_ring_art_raw = NULL;
        }
        if (s_ring_face_raw != NULL) {
            board_free_psram(s_ring_face_raw);
            s_ring_face_raw = NULL;
        }
        return false;
    }

    s_ring_art = (uint16_t *)(((uintptr_t)s_ring_art_raw +
                               (HELM_RING_ART_ALIGN - 1u)) &
                              ~(uintptr_t)(HELM_RING_ART_ALIGN - 1u));
    s_ring_face = (uint16_t *)(((uintptr_t)s_ring_face_raw +
                                (HELM_RING_ART_ALIGN - 1u)) &
                               ~(uintptr_t)(HELM_RING_ART_ALIGN - 1u));
    return true;
}

/** @brief 角度（0 = 12 点，顺时针）→ 200×200 art/face 的缓冲坐标。 */
static void helm_ring_pt_art(int angle, int r, int * x, int * y)
{
    int px;
    int py;

    helm_ring_pt(angle, r, &px, &py);
    *x = px - (HELM_RING_CX - HELM_RING_ART_W / 2);
    *y = py - (HELM_RING_CY - HELM_RING_ART_H / 2);
}

/**
 * @brief 重画 art（当前模式的静态图，扇区/指针都在 12 点方位）。
 *
 * @details 几何与旧对象逐项一致（旧对象仍在，但 canvas 路径下隐藏）：
 *   外圈 2px = lv_arc 半径 100 / 宽 2（98..100）；
 *   扇区 16px = 半径 100 / 宽 16（84..100），跨 52°（244..296，中心 270 = 12 点）；
 *   深色外沿 2px = 半径 100 / 宽 2；
 *   刻度 = 与 helm_ring_build_ticks 同一组 x,y,w,h + 圆角 th/2；
 *   指针 = 3px 圆头线 r=74→96 + 末端 11px 横杆。
 * 这是一次性成本（模式/主题变化才重画），动画帧不碰它。
 */
static void helm_ring_art_draw(int mode)
{
    lv_layer_t layer;
    lv_draw_rect_dsc_t rect;
    lv_draw_arc_dsc_t arc;
    lv_draw_line_dsc_t line;
    lv_area_t full;
    const int cx = HELM_RING_ART_W / 2;
    const int cy = HELM_RING_ART_H / 2;
    int x1 = 0;
    int y1 = 0;
    int x2 = 0;
    int y2 = 0;

    if (s_ring_art_cv == NULL || s_ring_art == NULL) {
        return;
    }

    mode &= 3;
    full.x1 = 0;
    full.y1 = 0;
    full.x2 = HELM_RING_ART_W - 1;
    full.y2 = HELM_RING_ART_H - 1;

    lv_canvas_init_layer(s_ring_art_cv, &layer);

    /* 纸底（不透明：旋转后四角保持纸色，face 不需要每帧预填）。 */
    lv_draw_rect_dsc_init(&rect);
    rect.bg_color = helm_color(HELM_COLOR_PAPER);
    rect.bg_opa = LV_OPA_COVER;
    lv_draw_rect(&layer, &rect, &full);

    /* R1-S7c：外圈留在 art 里（旋转不变，圆形转还是圆形），但必须画在扇区
     * **之前** —— 扇区的 2px 深色外沿要盖住它。24 刻度不进 art（静态对象在
     * canvas 之上），这样每帧只重绘转子（扇区+指针）的包围盒。
     * ⚠ 外圈不能交给 canvas 之下/之上的独立对象：canvas 是不透明纸底，
     *   放下面会被盖掉；放上面会反过来盖住扇区外沿（Codex 审查指出）。 */
    lv_draw_arc_dsc_init(&arc);
    arc.center.x = cx;
    arc.center.y = cy;
    arc.radius = (uint16_t)(HELM_RING_D / 2);
    arc.width = 2;
    arc.color = helm_color(HELM_COLOR_TRACK);
    arc.opa = LV_OPA_COVER;
    arc.start_angle = 0;
    arc.end_angle = 360;
    lv_draw_arc(&layer, &arc);

    /* 选中扇区 16px（半径 84..100），12 点方位、跨 52°。 */
    arc.width = 16;
    arc.color = helm_color(helm_ring_fill_hex(mode));
    arc.opa = ((mode & 3) == 3) ? (lv_opa_t)LV_OPA_20 : (lv_opa_t)LV_OPA_COVER;
    arc.start_angle = 244;    /* 270 - 26 */
    arc.end_angle = 296;      /* 270 + 26 */
    lv_draw_arc(&layer, &arc);

    /* 扇区 2px 深色外沿（半径 98..100）。 */
    arc.width = 2;
    arc.color = helm_color(helm_ring_ink_hex(mode));
    arc.opa = LV_OPA_COVER;
    lv_draw_arc(&layer, &arc);

    /* 指针 T（12 点方位）：杆 r=74→96、末端 11px 横杆；3px、圆头。 */
    lv_draw_line_dsc_init(&line);
    line.color = helm_color(HELM_COLOR_INK);
    line.width = 3;
    line.opa = LV_OPA_COVER;
    line.round_start = 1;
    line.round_end = 1;
    helm_ring_pt_art(0, HELM_RING_PTR_R0, &x1, &y1);
    helm_ring_pt_art(0, HELM_RING_PTR_R1, &x2, &y2);
    line.p1.x = x1;
    line.p1.y = y1;
    line.p2.x = x2;
    line.p2.y = y2;
    lv_draw_line(&layer, &line);
    line.p1.x = x2 - HELM_RING_PTR_CROSS;
    line.p1.y = y2;
    line.p2.x = x2 + HELM_RING_PTR_CROSS;
    line.p2.y = y2;
    lv_draw_line(&layer, &line);

    lv_canvas_finish_layer(s_ring_art_cv, &layer);
}

/**
 * @brief 一帧：art --EPIC--> face（RGB565、最近邻、返回时已停）。
 * @return false = EPIC 没执行（不可用/超时），调用方走 CPU 回退。
 */
static bool helm_ring_face_epic(int32_t angle)
{
    if (s_ring_art == NULL || s_ring_face == NULL) {
        return false;
    }

    return myvendor_epic_rotate(s_ring_art, (uint32_t)HELM_RING_ART_STRIDE,
                                HELM_RING_ART_W, HELM_RING_ART_H,
                                s_ring_face, (uint32_t)HELM_RING_ART_STRIDE,
                                HELM_RING_ART_W, HELM_RING_ART_H,
                                helm_ring_norm((int)angle) * 10,
                                HELM_RING_ART_W / 2, HELM_RING_ART_H / 2,
                                HELM_RING_ART_W / 2, HELM_RING_ART_H / 2);
}

/** @brief floor(v / 65536)（v 为负也向下取整；供 CPU 旋转用）。 */
static int32_t helm_ring_floor16(int64_t v)
{
    if (v >= 0) {
        return (int32_t)(v >> 16);
    }
    return (int32_t)(-(((-v) + 65535) >> 16));
}

/**
 * @brief CPU 最近邻回退（仅 EPIC 不可用/超时时走；与 EPIC 同一套语义）。
 *
 * @details 逆向映射：src = R(-θ)·(dst - center) + center，θ 顺时针。
 *          坐标按**像素中心**算（像素 i 覆盖 [i,i+1)，中心 i+0.5）—— 这与
 *          EPIC 的 pivot 语义一致（HAL 的 `EPIC_GetRotatedArea` 用 `w - pivot`），
 *          90° 的整数倍能把 200×200 网格**逐像素**映射回自己，不产生 1px 漂移。
 *          采样越界时保留 face 原像素（= 上一帧的纸色），与 EPIC 的
 *          "背景 = 目的层本身"一致。
 */
static void helm_ring_face_cpu(int32_t angle)
{
    const int a = helm_ring_norm((int)angle);
    const int32_t cs = lv_trigo_cos((int16_t)a);
    const int32_t sn = lv_trigo_sin((int16_t)a);
    const int32_t cx = HELM_RING_ART_W / 2;
    const int32_t cy = HELM_RING_ART_H / 2;
    int32_t y;

    if (s_ring_art == NULL || s_ring_face == NULL) {
        return;
    }

    for (y = 0; y < HELM_RING_ART_H; y++) {
        uint16_t *drow = s_ring_face + (size_t)y * HELM_RING_ART_W;
        const int32_t hy = 2 * y + 1 - 2 * cy;   /* 2 × (dy，以像素中心算) */
        int32_t x;

        for (x = 0; x < HELM_RING_ART_W; x++) {
            const int32_t hx = 2 * x + 1 - 2 * cx;
            const int64_t nx = (int64_t)cs * hx + (int64_t)sn * hy;
            const int64_t ny = -(int64_t)sn * hx + (int64_t)cs * hy;
            const int32_t sx = helm_ring_floor16(nx) + cx;
            const int32_t sy = helm_ring_floor16(ny) + cy;

            if (sx >= 0 && sy >= 0 && sx < HELM_RING_ART_W &&
                sy < HELM_RING_ART_H) {
                drow[x] = s_ring_art[(size_t)sy * HELM_RING_ART_W + (size_t)sx];
            }
        }
    }
}

/** @brief 把 art 转到 face（EPIC 优先，失败/不可用走 CPU），并标脏 canvas。 */
static void helm_ring_face_blit(int32_t angle)
{
    if (s_sh.ring_canvas == NULL || s_ring_face == NULL) {
        return;
    }

    if (!helm_ring_face_epic(angle)) {
        helm_ring_face_cpu(angle);
    }
    lv_obj_invalidate(s_sh.ring_canvas);
}

/**
 * @brief 建 ring art/face 的 canvas 对象（face 可见、art 隐藏）。
 * @return true = canvas 路径可用；false = 走旧对象 + CPU 指针动画。
 */
static bool helm_ring_canvas_build(void)
{
#if defined(__NuttX__)
    /* 板端：EPIC 是唯一可接受的速度。没有 EPIC 时 200×200 的 CPU 整层旋转
     * 每帧要几十 ms（比指针动画还慢），按任务约定直接退回 S7 的 CPU 指针动画；
     * 模拟器（非 __NuttX__）没有 EPIC 是常态，用 CPU 最近邻出中间帧。 */
    if (!myvendor_epic_ready()) {
        printf("[ring] epic unavailable -> cpu pointer anim\n");
        return false;
    }
#endif

    if (!helm_ring_art_alloc()) {
        printf("[ring] art alloc failed -> cpu pointer anim\n");
        return false;
    }

    s_sh.ring_canvas = lv_canvas_create(s_sh.ring);
    lv_canvas_set_buffer(s_sh.ring_canvas, s_ring_face, HELM_RING_ART_W,
                         HELM_RING_ART_H, LV_COLOR_FORMAT_RGB565);
    lv_obj_set_pos(s_sh.ring_canvas,
                   HELM_RING_CX - HELM_RING_ART_W / 2,
                   HELM_RING_CY - HELM_RING_ART_H / 2);
    lv_obj_remove_flag(s_sh.ring_canvas, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(s_sh.ring_canvas, LV_OBJ_FLAG_SCROLLABLE);

    s_ring_art_cv = lv_canvas_create(s_sh.ring);
    lv_canvas_set_buffer(s_ring_art_cv, s_ring_art, HELM_RING_ART_W,
                         HELM_RING_ART_H, LV_COLOR_FORMAT_RGB565);
    lv_obj_add_flag(s_ring_art_cv, LV_OBJ_FLAG_HIDDEN);
    lv_obj_remove_flag(s_ring_art_cv, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(s_ring_art_cv, LV_OBJ_FLAG_SCROLLABLE);

    printf("[ring] art %dx%d art=%p face=%p stride=%d align=%u psram=%d\n",
           HELM_RING_ART_W, HELM_RING_ART_H, (void *)s_ring_art,
           (void *)s_ring_face, (int)HELM_RING_ART_STRIDE,
           (unsigned)HELM_RING_ART_ALIGN,
           (board_ptr_in_psram_pool(s_ring_art) &&
            board_ptr_in_psram_pool(s_ring_face)) ? 1 : 0);
    return true;
}

/** @brief canvas 路径下把旧对象藏起来（CPU 回退路径仍要它们）。 */
static void helm_ring_hide_legacy(lv_obj_t * obj)
{
    if (obj != NULL && s_sh.ring_canvas != NULL) {
        lv_obj_add_flag(obj, LV_OBJ_FLAG_HIDDEN);
    }
}

/** @brief 标题行：名字 180 宽居中；20px 图标贴在文字墨迹左侧（同模拟器）。 */
static void helm_ring_title_layout(void)
{
    const lv_font_t * nf = helm_ring_name_font();
    lv_point_t sz;
    int left;

    if (s_sh.ring_name == NULL) {
        return;
    }
    lv_text_get_size(&sz, lv_label_get_text(s_sh.ring_name), nf, 0, 0,
                     LV_COORD_MAX, LV_TEXT_FLAG_NONE);
    left = HELM_RING_HUB_W / 2 - (int)sz.x / 2;
    lv_obj_set_pos(s_sh.ring_name, 0, 0);
    if (s_sh.ring_icon != NULL) {
        const int ly = (lv_font_get_line_height(nf) - 20) / 2;

        lv_obj_set_pos(s_sh.ring_icon, left - 2 - 20, (ly > 0) ? ly : 0);
    }
}

/** @brief 主值按 hub 中线居中；单位挂在右侧、与主值共用基线。 */
static void helm_ring_value_layout(const char * txt, bool has_unit,
                                   const char * unit)
{
    const lv_font_t * vf = s_sh.font_val;
    const lv_font_t * uf = s_sh.font_lab;
    lv_point_t sz;
    int vx;

    if (s_sh.ring_value == NULL) {
        return;
    }
    lv_text_get_size(&sz, txt, vf, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
    vx = HELM_RING_HUB_W / 2 - (int)sz.x / 2;
    lv_obj_set_pos(s_sh.ring_value, vx, 62);

    if (s_sh.ring_unit == NULL) {
        return;
    }
    if (!has_unit) {
        helm_show(s_sh.ring_unit, false);
        return;
    }

    {
        const int vb = lv_font_get_line_height(vf) - vf->base_line;
        const int ub = lv_font_get_line_height(uf) - uf->base_line;

        lv_obj_set_pos(s_sh.ring_unit, vx + (int)sz.x + 3, 62 + vb - ub);
    }
    helm_label_set(s_sh.ring_unit, unit);
    helm_show(s_sh.ring_unit, true);
}

/** @brief 换模式：名字/描述/图标（盘心模式名是唯一模式指示）。 */
static void helm_ring_paint_mode(int mode)
{
    mode &= 3;
    s_sh.ring_mode = (uint8_t)mode;
    if (s_sh.ring_name == NULL) {
        return;
    }

    helm_ring_set_font(s_sh.ring_name, helm_ring_name_font());
    helm_label_set(s_sh.ring_name, s_ring_names[mode]);
    helm_set_text_hex(s_sh.ring_name, HELM_COLOR_INK);
    helm_ring_title_layout();

    if (s_sh.ring_icon != NULL) {
        hfi_set(s_sh.ring_icon, helm_ring_icon_id(mode));
        lv_obj_set_style_text_color(s_sh.ring_icon,
                                    helm_color(helm_ring_ink_hex(mode)), 0);
    }
    helm_label_set(s_sh.ring_desc, s_ring_descs[mode]);
    helm_set_text_hex(s_sh.ring_desc, HELM_COLOR_MUTE);
}

/**
 * @brief 盘下统计行。
 * @details **缺口**：GPX 列表/周聚合在 `helm_menu.c` 里是私有表（本包只被允许
 *          新增 `helm_menu_open_at()`），helm_shell 拿不到"本周里程 / 次数 /
 *          最近日期" ⇒ 按任务允许的降级：显示"上次骑行 X km · 记录数未知"，
 *          7 根迷你柱保持隐藏（不自造内存周数据）。见 S2/NOTES.md。
 */
static void helm_ring_week_sync(void)
{
    char buf[64];

    if (s_sh.ring_week == NULL) {
        return;
    }
    if (s_sh.last_km > 0.05f) {
        char km[16];

        helm_fmt_km(km, sizeof(km), s_sh.last_km);
        /* 记录条数/周聚合要扫 GPX 目录（菜单私有表），本阶段拿不到就只报
         * 上次里程；写「记录数未知」比留空更难看，宁可不写。 */
        lv_snprintf(buf, sizeof(buf), "上次骑行 %s km", km);
    } else {
        lv_snprintf(buf, sizeof(buf), "暂无骑行记录");
    }
    helm_label_set(s_sh.ring_week, buf);
    helm_set_text_hex(s_sh.ring_week, HELM_COLOR_INK);
}

/** @brief 盘心数值 + 副行（每 500ms 刷新；只改文本与水平居中）。 */
static void helm_ring_paint_values(const bicycle_runtime_t * rt)
{
    char v[24];
    char u[8];
    char sub[64];
    char km[16];
    bool has_unit = false;
    const int mode = s_sh.ring_mode & 3;

    v[0] = '\0';
    u[0] = '\0';
    sub[0] = '\0';

    switch (mode) {
    case 0:
        /* 骑行：上次骑行里程（来源 = shell 既有的 last_km，即
         * myvendor_devctl_last_ride_m_get / 保存骑行时回写）。 */
        if (s_sh.last_km > 0.05f) {
            helm_fmt_km(km, sizeof(km), s_sh.last_km);
        } else {
            lv_snprintf(km, sizeof(km), "0.0");
        }
        lv_snprintf(v, sizeof(v), "%s", km);
        lv_snprintf(u, sizeof(u), "km");
        has_unit = true;
        if (helm_riding()) {
            char sp[16];

            helm_fmt_speed(sp, sizeof(sp), helm_session_avg_kph(rt));
            lv_snprintf(sub, sizeof(sub), "均速 %s km/h", sp);
        } else {
            /* 描述行已经是「上次骑行」，副行再写一遍就是重复。 */
            lv_snprintf(sub, sizeof(sub), "未开始骑行");
        }
        break;

    case 1:
        if (s_sh.map != NULL && map_page_nav_active(s_sh.map)) {
            double rem = map_page_nav_remain_m(s_sh.map);
            double tot = map_page_nav_total_m(s_sh.map);
            char tk[16];

            if (rem < 0.0) {
                rem = 0.0;
            }
            if (tot < 0.0) {
                tot = 0.0;
            }
            helm_fmt_km(km, sizeof(km), (float)(rem / 1000.0));
            helm_fmt_km(tk, sizeof(tk), (float)(tot / 1000.0));
            lv_snprintf(v, sizeof(v), "%s", km);
            lv_snprintf(u, sizeof(u), "km");
            has_unit = true;
            lv_snprintf(sub, sizeof(sub), "全程 %s km", tk);
        } else {
            lv_snprintf(v, sizeof(v), "--");
            lv_snprintf(sub, sizeof(sub), "未在导航");
        }
        break;

    case 2:
        /* 记录：拿不到 GPX 条数/最近日期 ⇒ 显示上次记录里程，副行"暂无"。 */
        if (s_sh.last_km > 0.05f) {
            helm_fmt_km(km, sizeof(km), s_sh.last_km);
        } else {
            lv_snprintf(km, sizeof(km), "0.0");
        }
        lv_snprintf(v, sizeof(v), "%s", km);
        lv_snprintf(u, sizeof(u), "km");
        has_unit = true;
        lv_snprintf(sub, sizeof(sub), "暂无记录日期");
        break;

    default: {
        int pct = myvendor_sys_battery_percent();
        const char * ver = myvendor_sw_version();

        if (pct < 0) {
            pct = 0;
        } else if (pct > 100) {
            pct = 100;
        }
        lv_snprintf(v, sizeof(v), "%d", pct);
        lv_snprintf(u, sizeof(u), "%%");
        has_unit = true;
        if (ver != NULL && ver[0] != '\0') {
            lv_snprintf(sub, sizeof(sub), "固件 %s", ver);
        } else {
            lv_snprintf(sub, sizeof(sub), "固件 --");
        }
        break;
    }
    }

    helm_label_set(s_sh.ring_value, v);
    helm_set_text_hex(s_sh.ring_value, HELM_COLOR_INK);
    helm_ring_value_layout(v, has_unit, u);
    helm_label_set(s_sh.ring_sub, sub);
    helm_set_text_hex(s_sh.ring_sub, HELM_COLOR_MUTE);
    helm_ring_week_sync();
}

static void helm_ring_paint_all(void)
{
    helm_ring_paint_mode(s_sh.ring_mode & 3);
    helm_ring_paint_values(bicycle_runtime_get());
}

/** @brief 500ms 节拍：只刷数值（模式切换是瞬时 snap，不在节拍里改）。 */
static void helm_ring_tick(const bicycle_runtime_t * rt)
{
    if (s_sh.ring == NULL) {
        return;
    }
    /* 系统 TTF 可能比首帧晚就绪：字体换了就按新字宽重排标题行，
     * 否则 30px 名字会一直停在开机时的 22px 回退档。 */
    if (s_sh.ring_name != NULL &&
        lv_obj_get_style_text_font(s_sh.ring_name, 0) != helm_ring_name_font()) {
        helm_ring_paint_mode(s_sh.ring_mode);
    }
    helm_ring_paint_values(rt);
}

/**
 * @brief 一次把扇区/指针/盘心落到目标模式（动画结束帧；无动画的 demo 也走这里）。
 * @details R1-S7b：canvas 路径下扇区/指针已经烘进 ring art —— 这里重画 art
 *          （换模式色）并把 face 转到 `mode*90°`；旧对象（弧/指针/刻度）只在
 *          缓冲分配失败的回退路径里可见，照旧删旧扇区、建新扇区、摆指针。
 */
static void helm_ring_apply(int mode)
{
    int i;

    mode &= 3;

    if (s_sh.ring == NULL) {
        s_sh.ring_mode = (uint8_t)mode;
        return;
    }

    for (i = 0; i < 2; i++) {
        if (s_sh.ring_fill[i] != NULL) {
            lv_obj_delete(s_sh.ring_fill[i]);
            s_sh.ring_fill[i] = NULL;
        }
        if (s_sh.ring_trk[i] != NULL) {
            lv_obj_delete(s_sh.ring_trk[i]);
            s_sh.ring_trk[i] = NULL;
        }
    }

    s_sh.ring_mode = (uint8_t)mode;
    helm_ring_sector_make(mode);
    s_sh.ring_angle = (int32_t)mode * 90;
    helm_ring_pointer_layout(s_sh.ring_angle);
    helm_ring_paint_mode(mode);
    helm_ring_paint_values(bicycle_runtime_get());

    if (s_sh.ring_canvas != NULL) {
        helm_ring_art_draw(mode);
        if (!helm_ring_face_epic(s_sh.ring_angle)) {
            helm_ring_face_cpu(s_sh.ring_angle);
        }
        /* 动画刚跑完时只标脏转子（和上一帧并集）；首次摆页/回退路径整幅标脏。 */
        if (s_ring_rotor_prev_ok) {
            helm_ring_invalidate_rotor(s_sh.ring_angle);
        } else {
            lv_obj_invalidate(s_sh.ring_canvas);
            helm_ring_rotor_bbox((int)s_sh.ring_angle, &s_ring_rotor_prev);
            s_ring_rotor_prev_ok = true;
        }
    }
}

/** @brief 转子（扇区 ±26° + 指针 T）在页面坐标下的包围盒（含 4px 余量）。 */
static void helm_ring_rotor_bbox(int angle, lv_area_t * a)
{
    const int r_out = HELM_RING_D / 2;       /* 100 */
    const int r_in = r_out - 16;             /* 84：扇区内沿 */
    const int edges[2] = { angle - 26, angle + 26 };
    int32_t minx = 0x7FFFFFFF;
    int32_t miny = 0x7FFFFFFF;
    int32_t maxx = -0x7FFFFFFF;
    int32_t maxy = -0x7FFFFFFF;
    int i;

    for (i = 0; i < 2; i++) {
        int x;
        int y;

        helm_ring_pt(edges[i], r_in, &x, &y);
        minx = LV_MIN(minx, x); maxx = LV_MAX(maxx, x);
        miny = LV_MIN(miny, y); maxy = LV_MAX(maxy, y);
        helm_ring_pt(edges[i], r_out, &x, &y);
        minx = LV_MIN(minx, x); maxx = LV_MAX(maxx, x);
        miny = LV_MIN(miny, y); maxy = LV_MAX(maxy, y);
    }
    /* 指针杆 + 横杆两端（横杆 11px ≈ 在 r=96 上 ±7°）。 */
    {
        static const int pa[2] = { -7, 7 };
        int x;
        int y;

        helm_ring_pt(angle, HELM_RING_PTR_R0, &x, &y);
        minx = LV_MIN(minx, x); maxx = LV_MAX(maxx, x);
        miny = LV_MIN(miny, y); maxy = LV_MAX(maxy, y);
        for (i = 0; i < 2; i++) {
            helm_ring_pt(angle + pa[i], HELM_RING_PTR_R1, &x, &y);
            minx = LV_MIN(minx, x); maxx = LV_MAX(maxx, x);
            miny = LV_MIN(miny, y); maxy = LV_MAX(maxy, y);
        }
    }

    a->x1 = (int32_t)minx - 4;
    a->y1 = (int32_t)miny - 4;
    a->x2 = (int32_t)maxx + 4;
    a->y2 = (int32_t)maxy + 4;
}

/** @brief 只把转子（旧角 ∪ 新角）的包围盒标脏；刻度/外圈/盘心不跟着刷。
 *  @details 整张 200×200 标脏在板端是 ~80 ms/帧（panel flush 40k px），
 *           这正是"转起来卡"的根因；转子脏区通常只有 4~10k px。 */
static void helm_ring_invalidate_rotor(int32_t angle)
{
    lv_area_t a;
    lv_area_t u;
    lv_area_t org;

    if (s_sh.ring_canvas == NULL || s_sh.ring == NULL) {
        return;
    }

    helm_ring_rotor_bbox((int)angle, &a);
    if (s_ring_rotor_prev_ok) {
        u.x1 = LV_MIN(a.x1, s_ring_rotor_prev.x1);
        u.y1 = LV_MIN(a.y1, s_ring_rotor_prev.y1);
        u.x2 = LV_MAX(a.x2, s_ring_rotor_prev.x2);
        u.y2 = LV_MAX(a.y2, s_ring_rotor_prev.y2);
    } else {
        u = a;
    }

    lv_obj_get_coords(s_sh.ring, &org);
    u.x1 += org.x1;
    u.x2 += org.x1;
    u.y1 += org.y1;
    u.y2 += org.y1;
    lv_obj_invalidate_area(s_sh.ring_canvas, &u);

    s_ring_rotor_prev = a;
    s_ring_rotor_prev_ok = true;
}

/**
 * @brief 动画帧：整层 EPIC 旋转 + **只标脏转子包围盒**，不重画刻度/文字。
 * @details canvas 路径：每帧一次 `myvendor_epic_rotate(art → face)`；EPIC 不可用
 *          （模拟器）或超时（目的缓冲可能被写了一半）时用 CPU 最近邻重写整幅
 *          face，同一对 200×200 缓冲 —— 中间帧照样出得来，日志 epic=0。
 *          回退路径（art 分配失败）才重摆旧指针（S7 行为）。
 */
static void helm_ring_anim_exec(void * var, int32_t v)
{
    uint32_t now;

    (void)var;
    if (s_sh.ring_canvas != NULL) {
        const int32_t a10 = helm_ring_norm((int)v) * 10;
        uint32_t t0 = lv_tick_get();
        uint32_t rt;

        if (!myvendor_epic_rotate(s_ring_art, (uint32_t)HELM_RING_ART_STRIDE,
                                  HELM_RING_ART_W, HELM_RING_ART_H,
                                  s_ring_face, (uint32_t)HELM_RING_ART_STRIDE,
                                  HELM_RING_ART_W, HELM_RING_ART_H, a10,
                                  HELM_RING_ART_W / 2, HELM_RING_ART_H / 2,
                                  HELM_RING_ART_W / 2, HELM_RING_ART_H / 2)) {
            s_ring_anim_epic = 0;
            helm_ring_face_cpu(v);
        }
        rt = lv_tick_get() - t0;
        s_ring_anim_rot_sum += rt;
        if (rt > s_ring_anim_rot_max) {
            s_ring_anim_rot_max = rt;
        }
        helm_ring_invalidate_rotor(v);
    } else {
        helm_ring_pointer_layout(v);
    }

    now = lv_tick_get();
    if (s_ring_anim_frames != 0) {
        uint32_t dt = now - s_ring_anim_last;

        if (dt > s_ring_anim_maxdt) {
            s_ring_anim_maxdt = dt;
        }
    }
    s_ring_anim_last = now;
    s_ring_anim_frames++;
}

/** @brief 动画完成：扇区/盘心一次性落位，并打帧耗时供上板核对。 */
static void helm_ring_anim_done(lv_anim_t * a)
{
    (void)a;
    s_ring_anim_active = false;
    helm_ring_apply((int)s_ring_anim_to);
    printf("[ring] anim done mode=%u frames=%u maxdt=%ums epic=%u rotavg=%ums rotmax=%ums\n",
           (unsigned)s_ring_anim_to, (unsigned)s_ring_anim_frames,
           (unsigned)s_ring_anim_maxdt, (unsigned)s_ring_anim_epic,
           (unsigned)(s_ring_anim_frames ? (s_ring_anim_rot_sum /
                                            s_ring_anim_frames) : 0u),
           (unsigned)s_ring_anim_rot_max);
    s_ring_anim_last = 0;
    s_ring_anim_maxdt = 0;
    s_ring_anim_frames = 0;
    s_ring_anim_epic = 0;
    s_ring_anim_rot_sum = 0;
    s_ring_anim_rot_max = 0;
}

/** @brief 取消正在跑的旋转动画（重建 / 销毁环形页之前必须调）。
 *  @details lv_anim 的 var 是静态变量，不是 LVGL 对象 —— 页面删了动画仍会跑，
 *           下一帧就解引用已删除的 ring_canvas/ring_ptr。Codex 审查 P2 项。 */
static void helm_ring_anim_cancel(void)
{
    lv_anim_delete(&s_ring_anim_angle, helm_ring_anim_exec);
    s_ring_anim_active = false;
    s_ring_anim_frames = 0;
    s_ring_anim_last = 0;
    s_ring_anim_maxdt = 0;
    s_ring_anim_rot_sum = 0;
    s_ring_anim_rot_max = 0;
    s_ring_rotor_prev_ok = false;
}

/**
 * @brief 环转一格（整层 ring art 由 EPIC 旋转过去，落位时再换扇区色/盘心）。
 * @param dir +1 顺时针（KEY1 短，环形页下一个模式）、−1 逆时针。
 */
static void helm_ring_rotate(int dir)
{
    int from;
    int to;
    int32_t a0;
    lv_anim_t a;

    if (!s_sh.attached || s_sh.ring == NULL ||
        s_sh.view_id != HELM_PAGE_RING) {
        return;
    }
    if (dir == 0) {
        dir = 1;
    }

    /* 上一段还没跑完：先按它的目标落位，再从落位角起转，避免角度叠错。 */
    if (s_ring_anim_active) {
        lv_anim_delete(&s_ring_anim_angle, helm_ring_anim_exec);
        s_ring_anim_active = false;
        helm_ring_apply((int)s_ring_anim_to);
    }

    from = s_sh.ring_mode & 3;
    to = (from + ((dir > 0) ? 1 : 3)) & 3;
    a0 = s_sh.ring_angle;
    s_ring_anim_to = (uint8_t)to;
    s_ring_anim_frames = 0;
    s_ring_anim_last = lv_tick_get();
    s_ring_anim_maxdt = 0;
    s_ring_anim_rot_sum = 0;
    s_ring_anim_rot_max = 0;
    /* epic=1 的前提：canvas 路径就绪 **且** `myvendor_epic_ready()`；
     * 任一帧掉回 CPU 都会把这一位清 0（见 helm_ring_anim_exec）。 */
    s_ring_anim_epic = (s_sh.ring_canvas != NULL && myvendor_epic_ready()) ? 1 : 0;
    s_ring_anim_active = true;

    printf("[ring] anim mode=%d->%d a0=%d\n", from, to, (int)a0);

    lv_anim_init(&a);
    lv_anim_set_var(&a, &s_ring_anim_angle);
    lv_anim_set_values(&a, a0, a0 + dir * 90);
    lv_anim_set_duration(&a, HELM_RING_ANIM_MS);
    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
    lv_anim_set_exec_cb(&a, helm_ring_anim_exec);
    lv_anim_set_ready_cb(&a, helm_ring_anim_done);
    lv_anim_start(&a);
}

/**
 * @brief 进入当前模式。
 * @details 骑行 → 先开始/继续记录，再落到骑行页（DATA）；
 *          导航/记录/设置 → 菜单根行（0 / 4 / 6，0 基）。
 */
static void helm_ring_enter(int mode)
{
    switch (mode & 3) {
    case 0:
        /* 真按键进场：先解锁演示页，否则开始骑行后 apply_view 仍停在 RING。 */
        if (s_demo_page != (helm_page_id_t)0xff) {
            s_demo_page = (helm_page_id_t)0xff;
        }
        /* R1-S4a：环形→骑行清掉"停在环形"标志（暂停中也一样：ensure_ride 恢复）。 */
        s_sh.at_ring = false;
        helm_shell_ensure_ride();
        if (helm_riding()) {
            if (!helm_nav_on()) {
                s_sh.ride_idx = 0;
            }
            helm_apply_view();
            helm_refresh_numbers();
        }
        break;
    case 1:
        if (helm_menu_open_at(0) != 0) {
            printf("helm: ring menu(nav) open failed\n");
        }
        break;
    case 2:
        if (helm_menu_open_at(4) != 0) {
            printf("helm: ring menu(rides) open failed\n");
        }
        break;
    default:
        if (helm_menu_open_at(6) != 0) {
            printf("helm: ring menu(settings) open failed\n");
        }
        break;
    }
}

/** @brief 环形容器删除时停掉旋转动画（主题重建会删整棵 shell）。 */
static void helm_ring_deleted_cb(lv_event_t * e)
{
    LV_UNUSED(e);
    helm_ring_anim_cancel();
}

/**
 * @brief 搭建环形主页（挂在 MAP 页根，不新增 lv_pm 页）。
 * @details 全部绝对定位（父对象不设 flex）：几何与模拟器逐项对应。
 */
static void helm_build_ring(lv_obj_t * root)
{
    lv_obj_t * p;
    lv_obj_t * hair;
    int i;

    /* 重建前先停掉旧动画：var 是静态变量，不会随旧页面删除而失效。 */
    helm_ring_anim_cancel();

    s_sh.ring = lv_obj_create(root);
    lv_obj_add_event_cb(s_sh.ring, helm_ring_deleted_cb, LV_EVENT_DELETE, NULL);
    lv_obj_remove_style_all(s_sh.ring);
    helm_style_paper(s_sh.ring);
    lv_obj_set_style_bg_opa(s_sh.ring, LV_OPA_COVER, 0);

    lv_obj_set_style_bg_opa(s_sh.ring, LV_OPA_COVER, 0);
    lv_obj_set_size(s_sh.ring, PAGE_HOR_RES, HELM_PAGE_H);
    lv_obj_set_pos(s_sh.ring, 0, 0);
    lv_obj_add_flag(s_sh.ring, LV_OBJ_FLAG_FLOATING);
    lv_obj_add_flag(s_sh.ring, LV_OBJ_FLAG_HIDDEN);
    lv_obj_clear_flag(s_sh.ring, LV_OBJ_FLAG_CLICKABLE);

    /* R1-S7b：先建 ring art/face 的 canvas（在 hub 之下）；失败就退回旧对象。
     * 必须在 sector/ticks/pointer 之前 —— 那几个函数按 `ring_canvas` 是否存在
     * 决定把自己藏起来。 */
    s_sh.ring_canvas = NULL;
    (void)helm_ring_canvas_build();

    /* 外圈 2px track（模拟器 d2_ring 是 2px 描边圆，不是 arc）。 */
    p = lv_obj_create(s_sh.ring);
    lv_obj_remove_style_all(p);
    lv_obj_set_pos(p, HELM_RING_CX - HELM_RING_D / 2,
                   HELM_RING_CY - HELM_RING_D / 2);
    lv_obj_set_size(p, HELM_RING_D, HELM_RING_D);
    lv_obj_set_style_bg_opa(p, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(p, 2, 0);
    lv_obj_set_style_border_color(p, helm_color(HELM_COLOR_TRACK), 0);
    lv_obj_set_style_border_opa(p, LV_OPA_COVER, 0);
    lv_obj_set_style_radius(p, HELM_RING_D / 2, 0);
    lv_obj_remove_flag(p, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(p, LV_OBJ_FLAG_SCROLLABLE);
    s_sh.ring_track = p;
    /* R1-S7c：外圈已画进 art（在扇区之前）⇒ 这个对象只在无 canvas 的回退路径里用。 */
    helm_ring_hide_legacy(p);

    s_sh.ring_fill[0] = NULL;
    s_sh.ring_fill[1] = NULL;
    s_sh.ring_trk[0] = NULL;
    s_sh.ring_trk[1] = NULL;
    helm_ring_sector_make(s_sh.ring_mode & 3);

    helm_ring_build_ticks(s_sh.ring);

    /* 指针 + 横杆：lv_line 只存点数组指针 ⇒ 点放在 shell 静态结构里。 */
    s_sh.ring_ptr = lv_line_create(s_sh.ring);
    lv_obj_remove_style_all(s_sh.ring_ptr);
    lv_line_set_points(s_sh.ring_ptr, s_sh.ring_ptr_pts, 2);
    lv_obj_set_style_line_width(s_sh.ring_ptr, 3, 0);
    lv_obj_set_style_line_color(s_sh.ring_ptr, helm_color(HELM_COLOR_INK), 0);
    lv_obj_set_style_line_opa(s_sh.ring_ptr, LV_OPA_COVER, 0);
    lv_obj_set_style_line_rounded(s_sh.ring_ptr, true, 0);
    lv_obj_remove_flag(s_sh.ring_ptr, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(s_sh.ring_ptr, LV_OBJ_FLAG_SCROLLABLE);
    helm_ring_hide_legacy(s_sh.ring_ptr);

    s_sh.ring_cross = lv_line_create(s_sh.ring);
    lv_obj_remove_style_all(s_sh.ring_cross);
    lv_line_set_points(s_sh.ring_cross, s_sh.ring_cross_pts, 2);
    lv_obj_set_style_line_width(s_sh.ring_cross, 3, 0);
    lv_obj_set_style_line_color(s_sh.ring_cross, helm_color(HELM_COLOR_INK), 0);
    lv_obj_set_style_line_opa(s_sh.ring_cross, LV_OPA_COVER, 0);
    lv_obj_set_style_line_rounded(s_sh.ring_cross, true, 0);
    lv_obj_remove_flag(s_sh.ring_cross, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(s_sh.ring_cross, LV_OBJ_FLAG_SCROLLABLE);
    helm_ring_hide_legacy(s_sh.ring_cross);

    /* 盘心容器：图标 + 模式名同行、描述、数值 + 单位、发丝线、副行。 */
    s_sh.ring_hub = lv_obj_create(s_sh.ring);
    lv_obj_remove_style_all(s_sh.ring_hub);
    lv_obj_set_pos(s_sh.ring_hub, HELM_RING_HUB_X, HELM_RING_HUB_Y);
    lv_obj_set_size(s_sh.ring_hub, HELM_RING_HUB_W, HELM_RING_HUB_H);
    lv_obj_clear_flag(s_sh.ring_hub, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_clear_flag(s_sh.ring_hub, LV_OBJ_FLAG_CLICKABLE);

    s_sh.ring_name = helm_lab(s_sh.ring_hub, helm_ring_name_font(),
                              HELM_COLOR_INK, "");
    lv_obj_set_pos(s_sh.ring_name, 0, 0);
    lv_obj_set_width(s_sh.ring_name, HELM_RING_HUB_W);
