static void tour_log(const char *fmt, ...)
{
    va_list ap;

    fputs("[tour] ", stdout);
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
    fputc('\n', stdout);
    fflush(stdout);
}

static void tour_finish(void);

/** `mkdir -p`：逐级建目录（已存在不算错）。 */
static bool tour_mkdir_p(const char *dir)
{
    char tmp[sizeof(s_tour.dir)];
    size_t len = strlen(dir);

    if (len == 0 || len >= sizeof(tmp)) {
        return false;
    }
    memcpy(tmp, dir, len + 1);

    for (char *p = tmp + 1; *p; p++) {
        if (*p != '/') {
            continue;
        }
        *p = '\0';
        if (mkdir(tmp, 0777) != 0 && errno != EEXIST) {
            return false;
        }
        *p = '/';
    }
    if (mkdir(tmp, 0777) != 0 && errno != EEXIST) {
        return false;
    }
    return true;
}

/** 整屏失效后同步刷一遍，把影子缓冲补成完整一帧，再写 PNG。 */
static void tour_take_shot(const char *name)
{
    char path[sizeof(s_tour.dir) + 64];
    const uint16_t *fb;
    int w = 0;
    int h = 0;

    lv_obj_invalidate(lv_screen_active());
    lv_refr_now(NULL);

    fb = sim_display_shadow(&w, &h);
    if (snprintf(path, sizeof(path), "%s/%s.png", s_tour.dir, name) >= (int)sizeof(path)) {
        fprintf(stderr, "[tour] path too long: %s/%s.png\n", s_tour.dir, name);
        s_tour.failed = true;
        tour_finish();
        return;
    }

    if (sim_png_write(path, fb, w, h)) {
        tour_log("shot %s (%dx%d) page=%s theme=%s tick=%u", path, w, h,
                 tour_page_name((int)lvgl_page_current_id()),
                 lvgl_page_theme_name(), (unsigned)lv_tick_get());
        /* 地图页的米/像素：比例尺显隐的判据（helm_shell.c 的 mpp > 0）。 */
        if (lvgl_page_current_id() == BICYCLE_PM_ID_MAP && lvgl_page_map() != NULL) {
            tour_log("  map mpp=%.3f m/px (scale bar shown when > 0)",
                     map_page_map_mpp(lvgl_page_map()));
        }
    } else {
        fprintf(stderr, "[tour] shot FAILED %s\n", path);
        s_tour.failed = true;
        tour_finish();
    }
}

/** 开机结束的判据：splash 已 pop、无转场在跑、LiveMap 实例已建。 */
static bool tour_boot_ready(void)
{
    bicycle_pm_id_t id = lvgl_page_current_id();

    if (lv_pm_nav_busy()) {
        return false;
    }
    if (id == BICYCLE_PM_ID_STARTUP) {
        return false;
    }
    return lvgl_page_map() != NULL;
}

static void tour_next_step(void)
{
    s_tour.step++;
    s_tour.waited = 0;
    s_tour.nav_wait = 0;
}

static void tour_finish(void)
{
    s_tour.done = true;
    sim_ui_mtp_force_attached = false;
    if (s_tour.tmr) {
        lv_timer_delete(s_tour.tmr);
        s_tour.tmr = NULL;
    }
    tour_log("%s (dir=%s, frames=%d)", s_tour.failed ? "done WITH ERRORS" : "done",
             s_tour.dir, s_tour.frames);
    tour_log("note: page_factory skipped (CONFIG_MYVENDOR_FACTORY_MODE off in sim)");
}

static void tour_tick_cb(lv_timer_t *tmr)
{
    (void)tmr;

    if (!s_tour.started || s_tour.done || s_tour.failed) {
        return;
    }
    if (s_tour.step < 0 || s_tour.step >= s_step_count) {
        tour_finish();
        return;
    }

    const tour_step_t *st = &s_steps[s_tour.step];

    switch (st->kind) {
        case TOUR_ST_BOOT:
            s_tour.boot_wait++;
            if (tour_boot_ready()) {
                tour_log("boot: splash finished, page=%s, waited %d ticks (%u ms virtual)",
                         tour_page_name((int)lvgl_page_current_id()),
                         s_tour.boot_wait, (unsigned)s_tour.boot_wait * TOUR_TIMER_MS);
                tour_next_step();
            } else if (s_tour.boot_wait >= TOUR_BOOT_TIMEOUT) {
                tour_log("boot: timeout after %d ticks, current page=%s (continue)",
                         s_tour.boot_wait,
                         tour_page_name((int)lvgl_page_current_id()));
                tour_next_step();
            }
            return;

        case TOUR_ST_OPEN: {
            bicycle_pm_id_t cur = lvgl_page_current_id();

            if ((int)cur == st->arg) {
                tour_log("open %s: already current, skip", tour_page_name(st->arg));
            } else {
                int rc = lv_pm_open_page_msg((lv_pm_id)st->arg, LV_PM_MSG_NONE);

                if (rc == 0) {
                    tour_log("open %s: ok", tour_page_name(st->arg));
                } else {
                    tour_log("open %s: FAILED rc=%d", tour_page_name(st->arg), rc);
                    s_tour.failed = true;
                    tour_finish();
                    return;
                }
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_CLOSE: {
            bicycle_pm_id_t cur = lvgl_page_current_id();

            if ((int)cur != st->arg) {
                tour_log("close %s: not current (now %s), skip",
                         tour_page_name(st->arg), tour_page_name((int)cur));
            } else {
                int rc = lv_pm_close_page_msg(LV_PM_MSG_NONE);

                if (rc == 0) {
                    tour_log("close %s: ok", tour_page_name(st->arg));
                } else {
                    tour_log("close %s: FAILED rc=%d", tour_page_name(st->arg), rc);
                    s_tour.failed = true;
                    tour_finish();
                    return;
                }
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_THEME:
            if (lvgl_page_theme_set_by_name(st->name)) {
                tour_log("theme -> %s (now %s)", st->name, lvgl_page_theme_name());
            } else {
                tour_log("theme -> %s: FAILED (now %s)", st->name,
                         lvgl_page_theme_name());
                s_tour.failed = true;
                tour_finish();
                return;
            }
            tour_next_step();
            return;

        case TOUR_ST_DEMO_PAGE:
            if (st->name != NULL && helm_shell_demo_page(st->name)) {
                tour_log("demo page -> %s (current=%s)", st->name,
                         tour_page_name((int)lvgl_page_current_id()));
            } else {
                tour_log("demo page -> %s: FAILED", st->name ? st->name : "(null)");
                s_tour.failed = true;
                tour_finish();
                return;
            }
            tour_next_step();
            return;

        case TOUR_ST_DEMO_RING:
            helm_shell_demo_ring(st->arg);
            tour_log("demo ring mode=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_RIDE:
            helm_shell_demo_ride((float)st->arg / 10.0f);
            tour_log("demo ride speed=%.1f", (double)st->arg / 10.0);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_PAUSE:
            helm_shell_demo_pause(st->arg != 0);
            tour_log("demo pause=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_BOTTOM:
            helm_shell_demo_bottom(st->arg);
            tour_log("demo bottom=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_BANNER:
            helm_shell_demo_banner(st->arg);
            tour_log("demo banner=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DUMP_RIDE:
            helm_shell_demo_ride_dump();
            tour_next_step();
            return;

        case TOUR_ST_KEY:
            /* arg: 1/2 = KEY1/KEY2 短按；11/12 = 长按。 */
            helm_shell_demo_key(st->arg % 10, st->arg >= 10);
            tour_log("key inject KEY%d %s", st->arg % 10,
                     st->arg >= 10 ? "long" : "short");
            tour_next_step();
            return;

        case TOUR_ST_MENU_KEY:
            /* arg: 1/2 = KEY1/KEY2 短按；11/12 = 长按；21 = KEY1 双击。 */
            tour_log("key inject menu KEY%d kind=%d radio=%d", st->arg % 10,
                     st->arg / 10, myvendor_devctl_radio_get() ? 1 : 0);
            helm_menu_demo_key(st->arg % 10, st->arg / 10);
            tour_next_step();
            return;

        case TOUR_ST_MENU_DUMP:
            helm_menu_demo_key(0, 0);
            tour_log("menu dump radio=%d",
                     myvendor_devctl_radio_get() ? 1 : 0);
            tour_next_step();
            return;

        case TOUR_ST_PWR:
            /* arg: 1=单击 2=双击 3=长按 2s 4=取消确认框（真 helm_pwr 状态机）。 */
            tour_log("pwr inject %d", st->arg);
            helm_pwr_demo_action(st->arg);
            tour_next_step();
            return;

        case TOUR_ST_PWR_DUMP:
            helm_pwr_demo_dump();
            tour_next_step();
            return;

        case TOUR_ST_SAVE_DUMP:
            helm_shell_demo_save_dump();
            tour_next_step();
            return;

        case TOUR_ST_WAIT:
            if (st->arg > 0) {
                usleep((useconds_t)st->arg * 1000u);
            }
            tour_log("wait %d ms (real)", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DUMP:
            helm_shell_demo_ring_dump();
            tour_next_step();
            return;

        case TOUR_ST_SETTLE: {
            /* arg > 0：本步固定帧数；arg < 0：上限（不超过 --tour-frames）。 */
            int frames = s_tour.frames;

            if (st->arg > 0) {
                frames = st->arg;
            } else if (st->arg < 0 && frames > -st->arg) {
                frames = -st->arg;
            }

            /* 转场动画没完先等它；卡死就 drain（与板端抢占策略一致）。 */
            if (lv_pm_nav_busy()) {
                s_tour.nav_wait++;
                if (s_tour.nav_wait >= TOUR_NAV_TIMEOUT) {
                    tour_log("settle: nav busy %d ticks, drain", s_tour.nav_wait);
                    lv_pm_nav_drain();
                    s_tour.nav_wait = 0;
                    s_tour.waited = 0;
                }
                return;
            }

            if (s_tour.waited < frames) {
                s_tour.waited++;
                return;
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_SHOT:
            tour_take_shot(st->name);
            tour_next_step();
            return;

        case TOUR_ST_MTP:
            sim_ui_mtp_force_attached = (st->arg != 0);
            tour_log("mtp stub: %s", sim_ui_mtp_force_attached ? "host attached" : "host off");
            tour_next_step();
            return;

        case TOUR_ST_DONE:
        default:
            tour_finish();
            return;
    }
}

