/**
 * @brief 一段圆弧的折线点（page 坐标），a0→a1 顺时针，最多 max 点。
 * @return 实际点数（含两端）；max < 2 时返回 0。
 */
static int helm_ring_arc_pts(int a0, int a1, int r, int steps, lv_point_precise_t *pts, int max)
{
    int i;
    int n = steps;

    if (n < 2) n = 2;
    if (n > max) n = max;
    for (i = 0; i < n; i++) {
        const int a = a0 + (a1 - a0) * i / (n - 1);
        int x, y;
        helm_ring_pt(a, r, &x, &y);
        pts[i].x = x;
        pts[i].y = y;
    }
    return n;
}
