                                   pts[0], HELM_RING_CUR_PTS);
    return 1;
}

/**
 * @brief 把弧光标摆到 angle（页面坐标）。
 *
 * @details lv_line 的点是**相对对象左上角**的，且对象自身尺寸 = 点坐标最大值
 *          （`LV_EVENT_GET_SELF_SIZE`）⇒ 若把点写成页面绝对坐标，对象会从
 *          (0,0) 一直铺到光标位置、每帧标脏一大片。这里把对象摆到光标包围盒
 *          左上角、点写成相对坐标，于是 lv_obj_set_pos/lv_line_set_points 的
 *          自身标脏也只有 ~50×50 px。
 */
static void helm_ring_cursor_layout(int32_t angle)
{
    lv_point_precise_t abs_pts[2][HELM_RING_CUR_PTS];
    int seg_pts[2];
    const int segs = helm_ring_cursor_geom((int)angle, seg_pts, abs_pts);
    int s;

    for (s = 0; s < 2; s++) {
        lv_obj_t * obj = s_ring_cur[s];
        const int n = (s < segs) ? seg_pts[s] : 0;
        int32_t minx;
        int32_t miny;
        int i;

        if (obj == NULL) {
            continue;
        }
        if (n < 2) {
            lv_obj_add_flag(obj, LV_OBJ_FLAG_HIDDEN);
            continue;
        }

        minx = abs_pts[s][0].x;
        miny = abs_pts[s][0].y;
        for (i = 1; i < n; i++) {
            minx = LV_MIN(minx, abs_pts[s][i].x);
            miny = LV_MIN(miny, abs_pts[s][i].y);
        }
        /* 留 2px：相对坐标必须 ≥0（lv_line 的百分比/尺寸语义）。 */
        minx -= 2;
        miny -= 2;
        for (i = 0; i < n; i++) {
            s_ring_cur_pts[s][i].x = abs_pts[s][i].x - minx;
            s_ring_cur_pts[s][i].y = abs_pts[s][i].y - miny;
        }

        lv_obj_remove_flag(obj, LV_OBJ_FLAG_HIDDEN);
        lv_obj_set_pos(obj, minx, miny);
        lv_line_set_points(obj, s_ring_cur_pts[s], (uint32_t)n);
    }
}

/**
 * @brief 光标在页面坐标下的包围盒（含线宽/AA 余量）。
 * @details R1-S8 的"转子"只剩弧光标：动画帧的脏区 = 本帧 ∪ 上一帧包围盒，
 *          40×40~55×55 一档（~2~3k px），不再是 200×200（40k px）。
 */
static void helm_ring_rotor_bbox(int angle, lv_area_t * a)
{
    lv_point_precise_t pts[2][HELM_RING_CUR_PTS];
    int seg_pts[2];
    const int segs = helm_ring_cursor_geom(angle, seg_pts, pts);
    int32_t minx = 0x7FFFFFFF;
    int32_t miny = 0x7FFFFFFF;
    int32_t maxx = -0x7FFFFFFF;
    int32_t maxy = -0x7FFFFFFF;
    int s;

    for (s = 0; s < segs; s++) {
        int i;

        for (i = 0; i < seg_pts[s]; i++) {
            minx = LV_MIN(minx, pts[s][i].x);
            maxx = LV_MAX(maxx, pts[s][i].x);
            miny = LV_MIN(miny, pts[s][i].y);
            maxy = LV_MAX(maxy, pts[s][i].y);
        }
    }
    if (minx > maxx) {
        minx = maxx = HELM_RING_CX;
        miny = maxy = HELM_RING_CY;
    }
    a->x1 = minx - HELM_RING_CUR_MARGIN;
    a->y1 = miny - HELM_RING_CUR_MARGIN;
    a->x2 = maxx + HELM_RING_CUR_MARGIN;
    a->y2 = maxy + HELM_RING_CUR_MARGIN;
}

/** @brief 分配 art（80 KB + 32B 对齐余量）。失败返回 false。 */
static bool helm_ring_art_alloc(void)
{
    if (s_ring_art != NULL) {
        return true;
    }
    if (s_ring_art_raw == NULL) {
        s_ring_art_raw = board_malloc_psram(HELM_RING_ART_BYTES +
                                            HELM_RING_ART_ALIGN);
    }
    if (s_ring_art_raw == NULL) {
        return false;
    }

    s_ring_art = (uint16_t *)(((uintptr_t)s_ring_art_raw +
                               (HELM_RING_ART_ALIGN - 1u)) &
                              ~(uintptr_t)(HELM_RING_ART_ALIGN - 1u));
    return true;
}

/** @brief 角度（0 = 12 点，顺时针）→ 200×200 art 的缓冲坐标。 */
static void helm_ring_pt_art(int angle, int r, int * x, int * y)
{
    int px;
    int py;

    helm_ring_pt(angle, r, &px, &py);
    *x = px - (HELM_RING_CX - HELM_RING_ART_W / 2);
    *y = py - (HELM_RING_CY - HELM_RING_ART_H / 2);
}

/**
 * @brief 重画 ring art（当前模式/方案下的静态环底图，**不旋转**）。
 *
 * @details 图层顺序（全部一次性成本，动画帧不碰）：
 *   纸底 → 极浅环带（V1/V3，INK 7%，r 84..100）→ 内圈发丝线（r=72, 1px HAIR）
 *   → （V2）45 根细刻度（r 93..96, 1px MUTE）→ 外圈 2px TRACK（98..100）
 *   → 选中扇区 16px（r 84..100，mode 方位 ±26°）→ 扇区 2px 深色外沿。
 *   ⚠ 外圈必须画在扇区之前：扇区的 2px 深色外沿要盖住它（Codex 审查指出）。
 *   ⚠ 指针 T 已删除（R1-S8）：那里不再画任何杆/横杆。
 */
static void helm_ring_art_draw(int mode)
{
    lv_layer_t layer;
    lv_draw_rect_dsc_t rect;
    lv_draw_arc_dsc_t arc;
    lv_area_t full;
    const int cx = HELM_RING_ART_W / 2;
    const int cy = HELM_RING_ART_H / 2;
    int start;
    int end;
    int i;

    if (s_sh.ring_canvas == NULL || s_ring_art == NULL) {
        return;
    }

    mode &= 3;
    full.x1 = 0;
    full.y1 = 0;
    full.x2 = HELM_RING_ART_W - 1;
    full.y2 = HELM_RING_ART_H - 1;

    lv_canvas_init_layer(s_sh.ring_canvas, &layer);

    /* 纸底（不透明：四角与阴影都保持纸色）。 */
    lv_draw_rect_dsc_init(&rect);
    rect.bg_color = helm_color(HELM_COLOR_PAPER);
    rect.bg_opa = LV_OPA_COVER;
    lv_draw_rect(&layer, &rect, &full);

    lv_draw_arc_dsc_init(&arc);
    arc.center.x = cx;
    arc.center.y = cy;
    arc.radius = HELM_RING_D / 2;

    /* 1) 极浅环带（V1/V3）：把 84..100 环带整个压一层 7% 墨，选中扇区仍更亮。 */
    if (s_ring_style != HELM_RING_STYLE_TICKS) {
        arc.width = HELM_RING_BAND_W;
        arc.color = helm_color(HELM_COLOR_INK);
        arc.opa = HELM_RING_BAND_OPA;
        arc.start_angle = 0;
        arc.end_angle = 360;
        lv_draw_arc(&layer, &arc);
    }

    /* 2) 内圈发丝线 r=72：把盘心框住，与环带之间留 12px 呼吸。 */
    arc.radius = HELM_RING_HAIR_R;
    arc.width = 1;
    arc.color = helm_color(HELM_COLOR_HAIR);
    arc.opa = LV_OPA_COVER;
    arc.start_angle = 0;
    arc.end_angle = 360;
    lv_draw_arc(&layer, &arc);

    /* 3) V2 细刻度环：45 根 1px（r 93..96），与 24 根主刻度构成双层刻度。 */
    if (s_ring_style == HELM_RING_STYLE_TICKS) {
        for (i = 0; i < HELM_RING_FINE_N; i++) {
            const int deg = i * (360 / HELM_RING_FINE_N);
            int x1, y1, x2, y2, x, y, w, h;

            helm_ring_pt_art(deg, HELM_RING_FINE_RIN, &x1, &y1);
            helm_ring_pt_art(deg, HELM_RING_FINE_ROUT, &x2, &y2);
            if (LV_ABS(x2 - x1) >= LV_ABS(y2 - y1)) {
                x = (x1 < x2) ? x1 : x2;
                y = y1;
                w = LV_ABS(x2 - x1) + 1;
                h = 1;
            } else {
                x = x1;
                y = (y1 < y2) ? y1 : y2;
                w = 1;
                h = LV_ABS(y2 - y1) + 1;
            }
            lv_draw_rect_dsc_init(&rect);
            rect.bg_color = helm_color(HELM_COLOR_MUTE);
            rect.bg_opa = 150;
            rect.radius = 0;
            full.x1 = x;
            full.y1 = y;
            full.x2 = x + w - 1;
            full.y2 = y + h - 1;
            lv_draw_rect(&layer, &rect, &full);
        }
        full.x1 = 0;
        full.y1 = 0;
        full.x2 = HELM_RING_ART_W - 1;
        full.y2 = HELM_RING_ART_H - 1;
    }

    /* 4) 外圈 2px TRACK（98..100），必须在扇区之前。 */
    arc.radius = HELM_RING_D / 2;
    arc.width = 2;
    arc.color = helm_color(HELM_COLOR_TRACK);
    arc.opa = LV_OPA_COVER;
    arc.start_angle = 0;
    arc.end_angle = 360;
    lv_draw_arc(&layer, &arc);

    /* 5) 选中扇区 16px（84..100），画在**当前模式方位**（mode*90°，0=12 点）。 */
    start = helm_ring_norm(270 + mode * 90 - 26);
    end = helm_ring_norm(270 + mode * 90 + 26);
    if (end <= start) {
        end += 360;
    }
    arc.width = 16;
    arc.color = helm_color(helm_ring_fill_hex(mode));
    arc.opa = (mode == 3) ? (lv_opa_t)LV_OPA_20 : (lv_opa_t)LV_OPA_COVER;
    arc.start_angle = (lv_value_precise_t)start;
    arc.end_angle = (lv_value_precise_t)end;
    lv_draw_arc(&layer, &arc);

    /* 6) 扇区 2px 深色外沿（98..100）。 */
    arc.width = 2;
    arc.color = helm_color(helm_ring_ink_hex(mode));
    arc.opa = LV_OPA_COVER;
    lv_draw_arc(&layer, &arc);

    lv_canvas_finish_layer(s_sh.ring_canvas, &layer);
}

/**
 * @brief 建 ring art 的 canvas 对象（可见，s_ring_art 单缓冲）。
 * @return true = canvas 路径可用；false = 退回旧弧对象（无底图，但光标仍在）。
 */
static bool helm_ring_canvas_build(void)
{
    if (!helm_ring_art_alloc()) {
        printf("[ring] art alloc failed -> legacy arcs (no ring art)\n");
        return false;
    }

    s_sh.ring_canvas = lv_canvas_create(s_sh.ring);
    lv_canvas_set_buffer(s_sh.ring_canvas, s_ring_art, HELM_RING_ART_W,
                         HELM_RING_ART_H, LV_COLOR_FORMAT_RGB565);
    lv_obj_set_pos(s_sh.ring_canvas,
                   HELM_RING_CX - HELM_RING_ART_W / 2,
                   HELM_RING_CY - HELM_RING_ART_H / 2);
    lv_obj_remove_flag(s_sh.ring_canvas, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(s_sh.ring_canvas, LV_OBJ_FLAG_SCROLLABLE);

    printf("[ring] art %dx%d art=%p stride=%d align=%u psram=%d\n",
           HELM_RING_ART_W, HELM_RING_ART_H, (void *)s_ring_art,
           (int)HELM_RING_ART_STRIDE, (unsigned)HELM_RING_ART_ALIGN,
           board_ptr_in_psram_pool(s_ring_art) ? 1 : 0);
    return true;
}

