/**
 * @brief 重画 art（当前模式的静态图，扇区/指针都在 12 点方位）。
 *
 * @details 几何与旧对象逐项一致（旧对象仍在，但 canvas 路径下隐藏）：
 *   外圈 2px = lv_arc 半径 100 / 宽 2（98..100）；
 *   扇区 16px = 半径 100 / 宽 16（84..100），跨 52°（244..296，中心 270 = 12 点）；
 *   深色外沿 2px = 半径 100 / 宽 2；
 *   刻度 = 与 helm_ring_build_ticks 同一组 x,y,w,h + 圆角 th/2；
 *   指针 = 3px 圆头线 r=74→96 + 末端 11px 横杆。
 * 这是一次性成本（模式/主题变化才重画），动画帧不碰它。
 */
static void helm_ring_art_draw(int mode)
{
    lv_layer_t layer;
    lv_draw_rect_dsc_t rect;
    lv_draw_arc_dsc_t arc;
    lv_draw_line_dsc_t line;
    lv_area_t full;
    const int cx = HELM_RING_ART_W / 2;
    const int cy = HELM_RING_ART_H / 2;
    int x1 = 0;
    int y1 = 0;
    int x2 = 0;
    int y2 = 0;

    if (s_ring_art_cv == NULL || s_ring_art == NULL) {
        return;
    }

    mode &= 3;
    full.x1 = 0;
    full.y1 = 0;
    full.x2 = HELM_RING_ART_W - 1;
    full.y2 = HELM_RING_ART_H - 1;

    lv_canvas_init_layer(s_ring_art_cv, &layer);

    /* 纸底（不透明：旋转后四角保持纸色，face 不需要每帧预填）。 */
    lv_draw_rect_dsc_init(&rect);
    rect.bg_color = helm_color(HELM_COLOR_PAPER);
    rect.bg_opa = LV_OPA_COVER;
    lv_draw_rect(&layer, &rect, &full);

    /* R1-S7c：外圈留在 art 里（旋转不变，圆形转还是圆形），但必须画在扇区
     * **之前** —— 扇区的 2px 深色外沿要盖住它。24 刻度不进 art（静态对象在
     * canvas 之上），这样每帧只重绘转子（扇区+指针）的包围盒。
     * ⚠ 外圈不能交给 canvas 之下/之上的独立对象：canvas 是不透明纸底，
     *   放下面会被盖掉；放上面会反过来盖住扇区外沿（Codex 审查指出）。 */
    lv_draw_arc_dsc_init(&arc);
    arc.center.x = cx;
    arc.center.y = cy;
    arc.radius = (uint16_t)(HELM_RING_D / 2);
    arc.width = 2;
    arc.color = helm_color(HELM_COLOR_TRACK);
    arc.opa = LV_OPA_COVER;
    arc.start_angle = 0;
    arc.end_angle = 360;
    lv_draw_arc(&layer, &arc);

    /* 选中扇区 16px（半径 84..100），12 点方位、跨 52°。 */
    arc.width = 16;
    arc.color = helm_color(helm_ring_fill_hex(mode));
    arc.opa = ((mode & 3) == 3) ? (lv_opa_t)LV_OPA_20 : (lv_opa_t)LV_OPA_COVER;
    arc.start_angle = 244;    /* 270 - 26 */
    arc.end_angle = 296;      /* 270 + 26 */
    lv_draw_arc(&layer, &arc);

    /* 扇区 2px 深色外沿（半径 98..100）。 */
    arc.width = 2;
    arc.color = helm_color(helm_ring_ink_hex(mode));
    arc.opa = LV_OPA_COVER;
    lv_draw_arc(&layer, &arc);

    /* 指针 T（12 点方位）：杆 r=74→96、末端 11px 横杆；3px、圆头。 */
    lv_draw_line_dsc_init(&line);
    line.color = helm_color(HELM_COLOR_INK);
    line.width = 3;
    line.opa = LV_OPA_COVER;
    line.round_start = 1;
    line.round_end = 1;
    helm_ring_pt_art(0, HELM_RING_PTR_R0, &x1, &y1);
    helm_ring_pt_art(0, HELM_RING_PTR_R1, &x2, &y2);
    line.p1.x = x1;
    line.p1.y = y1;
    line.p2.x = x2;
    line.p2.y = y2;
    lv_draw_line(&layer, &line);
    line.p1.x = x2 - HELM_RING_PTR_CROSS;
    line.p1.y = y2;
    line.p2.x = x2 + HELM_RING_PTR_CROSS;
    line.p2.y = y2;
    lv_draw_line(&layer, &line);

    lv_canvas_finish_layer(s_ring_art_cv, &layer);
}

/**
 * @brief 一帧：art --EPIC--> face（RGB565、最近邻、返回时已停）。
 * @return false = EPIC 没执行（不可用/超时），调用方走 CPU 回退。
 */
static bool helm_ring_face_epic(int32_t angle)
{
    if (s_ring_art == NULL || s_ring_face == NULL) {
        return false;
    }

    return myvendor_epic_rotate(s_ring_art, (uint32_t)HELM_RING_ART_STRIDE,
                                HELM_RING_ART_W, HELM_RING_ART_H,
                                s_ring_face, (uint32_t)HELM_RING_ART_STRIDE,
                                HELM_RING_ART_W, HELM_RING_ART_H,
                                helm_ring_norm((int)angle) * 10,
                                HELM_RING_ART_W / 2, HELM_RING_ART_H / 2,
                                HELM_RING_ART_W / 2, HELM_RING_ART_H / 2);
}

/** @brief floor(v / 65536)（v 为负也向下取整；供 CPU 旋转用）。 */
static int32_t helm_ring_floor16(int64_t v)
{
    if (v >= 0) {
        return (int32_t)(v >> 16);
    }
    return (int32_t)(-(((-v) + 65535) >> 16));
}

/**
 * @brief CPU 最近邻回退（仅 EPIC 不可用/超时时走；与 EPIC 同一套语义）。
 *
 * @details 逆向映射：src = R(-θ)·(dst - center) + center，θ 顺时针。
 *          坐标按**像素中心**算（像素 i 覆盖 [i,i+1)，中心 i+0.5）—— 这与
 *          EPIC 的 pivot 语义一致（HAL 的 `EPIC_GetRotatedArea` 用 `w - pivot`），
 *          90° 的整数倍能把 200×200 网格**逐像素**映射回自己，不产生 1px 漂移。
 *          采样越界时保留 face 原像素（= 上一帧的纸色），与 EPIC 的
 *          "背景 = 目的层本身"一致。
 */
static void helm_ring_face_cpu(int32_t angle)
{
    const int a = helm_ring_norm((int)angle);
    const int32_t cs = lv_trigo_cos((int16_t)a);
    const int32_t sn = lv_trigo_sin((int16_t)a);
    const int32_t cx = HELM_RING_ART_W / 2;
    const int32_t cy = HELM_RING_ART_H / 2;
    int32_t y;

    if (s_ring_art == NULL || s_ring_face == NULL) {
        return;
    }

    for (y = 0; y < HELM_RING_ART_H; y++) {
        uint16_t *drow = s_ring_face + (size_t)y * HELM_RING_ART_W;
        const int32_t hy = 2 * y + 1 - 2 * cy;   /* 2 × (dy，以像素中心算) */
        int32_t x;

        for (x = 0; x < HELM_RING_ART_W; x++) {
            const int32_t hx = 2 * x + 1 - 2 * cx;
            const int64_t nx = (int64_t)cs * hx + (int64_t)sn * hy;
            const int64_t ny = -(int64_t)sn * hx + (int64_t)cs * hy;
            const int32_t sx = helm_ring_floor16(nx) + cx;
            const int32_t sy = helm_ring_floor16(ny) + cy;

